<script setup lang="ts">
import type { MedicineProduct } from '~/types/api'
const { request } = useApi(); const submitting = ref(false); const errorMessage = ref('')
const form = reactive({ name: '', active_ingredient: '', concentration: '', stock_unit: 'ml', reorder_level: '0', meat_withdrawal_days: 0, milk_withdrawal_days: 0, instructions: '' })
async function submit() { submitting.value = true; errorMessage.value = ''; try { await request<MedicineProduct>('/medicine/products/', { method: 'POST', body: form }); await navigateTo('/medicine') } catch { errorMessage.value = 'The medicine product could not be saved.' } finally { submitting.value = false } }
</script>
<template><section class="form-card wide"><p class="eyebrow">Medicine inventory</p><h1>Add medicine product</h1><form class="form-grid" @submit.prevent="submit"><label>Name <input v-model="form.name" required></label><label>Active ingredient <input v-model="form.active_ingredient"></label><label>Concentration <input v-model="form.concentration" placeholder="e.g. 100 mg/ml"></label><label>Stock unit <input v-model="form.stock_unit" required></label><label>Reorder level <input v-model="form.reorder_level" type="number" min="0" step="0.01" required></label><label>Meat withdrawal (days) <input v-model.number="form.meat_withdrawal_days" type="number" min="0" required></label><label>Milk withdrawal (days) <input v-model.number="form.milk_withdrawal_days" type="number" min="0" required></label><label class="full">Instructions <textarea v-model="form.instructions" rows="4" /></label><p v-if="errorMessage" class="error full">{{ errorMessage }}</p><div class="actions full"><NuxtLink to="/medicine">Cancel</NuxtLink><button :disabled="submitting">{{ submitting ? 'Saving…' : 'Add product' }}</button></div></form></section></template>
